$ErrorActionPreference = 'Stop'
$root = Join-Path $env:TEMP 'whisper-spikes'
$manifest = Get-Content -LiteralPath (Join-Path $root 'cuda-redist-12.8.0.json') -Raw | ConvertFrom-Json
$names = @('cuda_nvcc','cuda_cudart','libcublas','cuda_nvrtc','cuda_cccl','cuda_profiler_api','cuda_nvtx')
$archives = Join-Path $root 'cuda-archives'
$parts = Join-Path $root 'cuda-parts'
New-Item -ItemType Directory -Path $archives,$parts -Force | Out-Null
foreach ($name in $names) {
    $entry = $manifest.$name.'windows-x86_64'
    if (-not $entry) { throw "missing component $name" }
    $url = 'https://developer.download.nvidia.com/compute/cuda/redist/' + $entry.relative_path
    $zip = Join-Path $archives ([IO.Path]::GetFileName($entry.relative_path))
    if (-not (Test-Path -LiteralPath $zip)) {
        & curl.exe -L --fail --retry 2 --silent --show-error --output $zip $url
        if ($LASTEXITCODE -ne 0) { throw "download failed $name" }
    }
    $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $zip).Hash.ToLowerInvariant()
    if ($actual -ne $entry.sha256) { throw "hash mismatch $name" }
    $dest = Join-Path $parts $name
    if (-not (Test-Path -LiteralPath $dest)) {
        Expand-Archive -LiteralPath $zip -DestinationPath $dest -Force
    }
    Write-Output "$name $actual $dest"
}

use std::time::Instant;
use whisper_rs::{FullParams, SamplingStrategy, WhisperContext, WhisperContextParameters};
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 4 { return Err("usage: spike MODEL WAV cpu|gpu".into()); }
    let use_gpu = match args[3].as_str() { "cpu" => false, "gpu" => true, _ => return Err("mode".into()) };
    let mut reader = hound::WavReader::open(&args[2])?;
    let spec = reader.spec();
    if spec.channels != 1 || spec.sample_rate != 16000 || spec.bits_per_sample != 16 { return Err("expected 16k mono i16 wav".into()); }
    let pcm: Vec<f32> = reader.samples::<i16>().map(|x| x.map(|v| f32::from(v) / 32768.0)).collect::<Result<_, _>>()?;
    let mut context_params = WhisperContextParameters::default();
    context_params.use_gpu(use_gpu);
    let start = Instant::now();
    let context = WhisperContext::new_with_params(&args[1], context_params)?;
    let mut state = context.create_state()?;
    let mut params = FullParams::new(SamplingStrategy::Greedy { best_of: 1 });
    params.set_language(Some("fr"));
    params.set_print_special(false);
    params.set_print_progress(false);
    params.set_print_realtime(false);
    params.set_print_timestamps(false);
    state.full(params, &pcm)?;
    println!("mode_requested={} elapsed_ms={} samples={} segments={}", args[3], start.elapsed().as_millis(), pcm.len(), state.as_iter().count());
    for segment in state.as_iter() { println!("{}-{} {}", segment.start_timestamp(), segment.end_timestamp(), segment); }
    Ok(())
}

use std::{fs::File, path::Path};
use symphonia::core::{errors::Error, formats::FormatOptions, io::MediaSourceStream, meta::MetadataOptions, probe::Hint, codecs::DecoderOptions};
fn main() -> Result<(), Box<dyn std::error::Error>> {
 for arg in std::env::args().skip(1) {
  let path=Path::new(&arg);
  let source=MediaSourceStream::new(Box::new(File::open(path)?),Default::default());
  let mut hint=Hint::new();
  if let Some(ext)=path.extension().and_then(|x| x.to_str()) { hint.with_extension(ext); }
  let probe=symphonia::default::get_probe().format(&hint,source,&FormatOptions::default(),&MetadataOptions::default())?;
  let mut format=probe.format;
  let track=format.default_track().ok_or("no track")?;
  let id=track.id;
  let rate=track.codec_params.sample_rate.unwrap_or(0);
  let channels=track.codec_params.channels.map(|x|x.count()).unwrap_or(0);
  let mut decoder=symphonia::default::get_codecs().make(&track.codec_params,&DecoderOptions::default())?;
  let mut frames=0u64;
  let mut packets=0u64;
  loop { match format.next_packet() {
   Ok(packet) if packet.track_id()==id => { let decoded=decoder.decode(&packet)?; frames+=decoded.frames() as u64; packets+=1; },
   Ok(_) => {},
   Err(Error::IoError(e)) if e.kind()==std::io::ErrorKind::UnexpectedEof => break,
   Err(e) => return Err(e.into()),
  }}
  println!("{} rate={} channels={} frames={} packets={} duration_ms={}",path.display(),rate,channels,frames,packets,frames*1000/u64::from(rate));
 }
 Ok(())
}

"""Disposable Windows crash-boundary probe; not product implementation."""
import hashlib
import json
import os
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).parent / "storage-fixture"
ORIGINAL = Path(r"C:\WhisperLive\micro_test.wav")


def digest(data):
    return hashlib.sha256(data).hexdigest()


def sync_write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("wb") as file:
        file.write(data)
        file.flush()
        os.fsync(file.fileno())


def artifact_set(kind):
    if kind == "live":
        return {"passage-1.mp3": b"MP3-demo", "transcript.txt": b"texte", "transcript.srt": b"1\n00:00:00,000 --> 00:00:01,000\ntexte\n"}
    return {"transcript.txt": b"texte", "transcript.srt": b"1\n00:00:00,000 --> 00:00:01,000\ntexte\n"}


def publish(folder, kind, crash_at):
    artifacts = artifact_set(kind)
    folder.mkdir(parents=True, exist_ok=True)
    if crash_at == 0:
        os._exit(42)
    for index, (name, data) in enumerate(artifacts.items(), 1):
        sync_write(folder / (name + ".pending"), data)
        if crash_at == index:
            os._exit(42)
    for index, name in enumerate(artifacts, 1):
        os.replace(folder / (name + ".pending"), folder / name)
        if crash_at == len(artifacts) + index:
            os._exit(42)
    marker = {
        "kind": kind,
        "artifacts": {name: digest(data) for name, data in artifacts.items()},
        "source": str(ORIGINAL) if kind == "import" else None,
    }
    sync_write(folder / "complete.json.pending", json.dumps(marker, sort_keys=True).encode())
    if crash_at == len(artifacts) * 2 + 1:
        os._exit(42)
    os.replace(folder / "complete.json.pending", folder / "complete.json")
    if crash_at == len(artifacts) * 2 + 2:
        os._exit(42)


def recover(folder):
    marker_path = folder / "complete.json"
    if not marker_path.exists():
        return "Recoverable"
    try:
        marker = json.loads(marker_path.read_bytes())
        required = set(artifact_set(marker["kind"]))
        if set(marker["artifacts"]) != required:
            return "Recoverable"
        if marker["kind"] == "import" and marker["source"] != str(ORIGINAL):
            return "Recoverable"
        if any(not (folder / name).is_file() or digest((folder / name).read_bytes()) != sha for name, sha in marker["artifacts"].items()):
            return "Recoverable"
        return "Complete"
    except (OSError, ValueError, KeyError, TypeError):
        return "Recoverable"


def queue(folder, phase):
    folder.mkdir(parents=True, exist_ok=True)
    entry = {"id": "import-1", "source": str(ORIGINAL), "status": "queued", "order": 1}
    sync_write(folder / "queue.json.pending", json.dumps(entry, sort_keys=True).encode())
    if phase == 1:
        os._exit(42)
    os.replace(folder / "queue.json.pending", folder / "queue.json")
    if phase == 2:
        os._exit(42)


def main():
    if len(sys.argv) == 5 and sys.argv[1] == "child":
        folder = Path(sys.argv[3])
        phase = int(sys.argv[4])
        if sys.argv[2] == "queue":
            queue(folder, phase)
        else:
            publish(folder, sys.argv[2], phase)
        return
    source_before = digest(ORIGINAL.read_bytes())
    results = []
    for kind in ("live", "import"):
        count = len(artifact_set(kind))
        for phase in range(0, count * 2 + 4):
            folder = ROOT / f"{kind}-{phase}"
            child = subprocess.run([sys.executable, __file__, "child", kind, str(folder), str(phase)], check=False)
            state = recover(folder)
            expect = "Complete" if phase >= count * 2 + 2 else "Recoverable"
            assert state == expect, (kind, phase, state, expect)
            results.append({"kind": kind, "phase": phase, "exit": child.returncode, "state": state})
    folder = ROOT / "tamper"
    publish(folder, "live", -1)
    assert recover(folder) == "Complete"
    (folder / "transcript.txt").write_bytes(b"tampered")
    assert recover(folder) == "Recoverable"
    for phase in (1, 2, 3):
        folder = ROOT / f"queue-{phase}"
        child = subprocess.run([sys.executable, __file__, "child", "queue", str(folder), str(phase)], check=False)
        exists = (folder / "queue.json").exists()
        assert exists == (phase != 1)
        results.append({"kind": "queue", "phase": phase, "exit": child.returncode, "durable_entry": exists})
    assert source_before == digest(ORIGINAL.read_bytes())
    print(json.dumps({"schema": "whisper-storage-spike/1", "python": sys.version, "os": os.name, "source_sha256": source_before, "cases": results, "tamper": "Recoverable", "source_unchanged": True, "limitation": "Process exit injection, not physical power loss; no directory fsync on Windows"}, sort_keys=True))


if __name__ == "__main__":
    main()
